pinned header and footer around a scrolling body // padding on layout reaches every slot, so all three align.
<layout
  padding={4}
  defaulthasdividers
  header={<layoutheader>{/* title + primary action */}</layoutheader>}
  content={<layoutcontent>{/* rows */}</layoutcontent>}
  footer={<layoutfooter>{/* save and cancel */}</layoutfooter>}
/>

fixed panel, then the resizable form // recommended panel width: 340–420.
<layout
  content={<layoutcontent>{/* rows */}</layoutcontent>}
  end={
    <layoutpanel width={380} hasdivider isscrollable label="details">
      {/* detail fields, or emptystate when nothing is selected */}
    </layoutpanel>
  }
/>

// resizable: handle first in an end slot, and isreversed so
// dragging left widens the panel.
end={
  <>
    <resizehandle isreversed hasdivider resizable={panel.props}
      label="resize details" />
    <layoutpanel width={panel.size} hasdivider={false} />
  </>
}

using token imports import * as stylex from '@stylexjs/stylex';
import {colorvars, spacingvars, sizevars, radiusvars} from '@astryxdesign/core/theme/tokens.stylex';
import {datavars} from '@astryxdesign/core/theme/datatokens.stylex';

const styles = stylex.create({
  card: {
    padding: spacingvars['--spacing-4'],
    backgroundcolor: colorvars['--color-background-surface'],
    borderradius: radiusvars['--radius-container'],
  },
  series: {
    color: datavars['--color-data-categorical-blue'],
  },
  button: {
    height: sizevars['--size-element-md'],
  },
});

